public class Cuenta {
    private double saldo;
    private final String titular;

    public Cuenta(String titular, double saldoInicial) {
        if (saldoInicial < 0) throw new IllegalArgumentException();
        this.titular = titular;
        this.saldo = saldoInicial;
    }

    public void depositar(double monto) {
        if (monto <= 0) throw new IllegalArgumentException();
        saldo += monto;
    }

    public void retirar(double monto) {
        if (monto <= 0 || monto > saldo) throw new IllegalArgumentException();
        saldo -= monto;
    }

    public double getSaldo() {
        return saldo;
    }

    public String getTitular() {
        return titular;
    }
}

public final class Periodo {
    private final LocalDate inicio;
    private final LocalDate fin;
    private final List<String> etiquetas;

    public Periodo(LocalDate inicio, LocalDate fin, List<String> etiquetas) {
        this.inicio = inicio;
        this.fin = fin;
        // Copia defensiva al recibir
        this.etiquetas = List.copyOf(etiquetas);
    }

    public LocalDate getInicio() { return inicio; }
    public LocalDate getFin() { return fin; }

    // Copia defensiva al devolver
    public List<String> getEtiquetas() {
        return List.copyOf(etiquetas);
    }
}

public final class Equipo {
