public interface Printable {
    void print();

    // Metodo default: implementacion por defecto
    default void printPretty() {
        log("Imprimiendo formato bonito");
        print();
    }

    // Metodo static: pertenece a la interfaz
    static Printable fromString(String s) {
        return () -> System.out.println(s);
    }

    // Metodo privado: solo para uso interno (Java 9+)
    private void log(String s) {
        System.out.println("[LOG] " + s);
    }
}

public abstract class Vehiculo {
    protected int velocidad;
    protected String marca;

    public Vehiculo(String marca) {
        this.marca = marca;
        this.velocidad = 0;
    }

    public abstract void acelerar(int incremento);
    public abstract void frenar();

    public void mostrarEstado() {
        System.out.println(marca + " a " + velocidad + " km/h");
    }
}

public class Coche extends Vehiculo {
    public Coche(String marca) {
        super(marca);
    }

    @Override
    public void acelerar(int incremento) {
        velocidad = Math.min(velocidad + incremento, 200);
    }

    @Override
    public void frenar() {
        velocidad = Math.max(velocidad - 50, 0);
    }
}

