public interface EstrategiaDescuento {
    double calcular(double precio);
}

public class DescuentoPorcentaje implements EstrategiaDescuento {
    private final double porcentaje;
    public DescuentoPorcentaje(double porcentaje) {
        this.porcentaje = porcentaje;
    }
    @Override
    public double calcular(double precio) {
        return precio * (1 - porcentaje / 100);
    }
}

public class Carrito {
    private EstrategiaDescuento descuento;

    public void setDescuento(EstrategiaDescuento descuento) {
        this.descuento = descuento;
    }

    public double totalConDescuento(double precio) {
        return descuento.calcular(precio);
    }
}

// En runtime:
