// Decorator: agrega timestamp
public class TimestampLogger implements Logger {
    private final Logger delegado;

    public TimestampLogger(Logger delegado) {
        this.delegado = delegado;
    }

    @Override
    public void log(String mensaje) {
        delegado.log("[" + java.time.LocalTime.now() + "] " + mensaje);
    }
}

// Composicion: combinar comportamientos
